package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.NullArgumentException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_tanh_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testTanh_NaN() {
        Complex c = Complex.NaN;
        Complex result = c.tanh();
        Assert.assertTrue("Result should be NaN", result.isNaN());
    }

    @Test
    public void testTanh_Zero() {
        Complex c = new Complex(0.0, 0.0);
        Complex result = c.tanh();
        Assert.assertEquals(0.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_RealOnly() {
        // tanh(x) for real x
        double x = 1.0;
        Complex c = new Complex(x, 0.0);
        Complex result = c.tanh();

        double expectedReal = Math.tanh(x);
        // For real x, imaginary part of tanh(x + 0i) should be 0
        Assert.assertEquals(expectedReal, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_ImaginaryOnly() {
        // tanh(iy) = i * tan(y)
        double y = Math.PI / 4.0;
        Complex c = new Complex(0.0, y);
        Complex result = c.tanh();

        // tan(PI/4) = 1.0. Result should be 0 + 1.0i
        Assert.assertEquals(0.0, result.getReal(), EPSILON);
        Assert.assertEquals(1.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_ComplexValue() {
        // Test with a general complex number
        double re = 0.5;
        double im = 0.5;
        Complex c = new Complex(re, im);
        Complex result = c.tanh();

        // Manual calculation using the formula provided in the method:
        // d = cosh(2*re) + cos(2*im)
        // real = sinh(2*re) / d
        // imag = sin(2*im) / d
        double real2 = 2.0 * re;
        double imag2 = 2.0 * im;
        double d = Math.cosh(real2) + Math.cos(imag2);
        double expectedReal = Math.sinh(real2) / d;
        double expectedImag = Math.sin(imag2) / d;

        Assert.assertEquals(expectedReal, result.getReal(), EPSILON);
        Assert.assertEquals(expectedImag, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_LargeReal() {
        // As real part goes to infinity, tanh(z) approaches 1
        Complex c = new Complex(100.0, 0.0);
        Complex result = c.tanh();
        Assert.assertEquals(1.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_NegativeReal() {
        // tanh(-x) = -tanh(x)
        Complex c = new Complex(-1.0, 0.0);
        Complex result = c.tanh();
        Assert.assertEquals(-Math.tanh(1.0), result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_NegativeImaginary() {
        // tanh(x - iy) = conjugate(tanh(x + iy))
        Complex c = new Complex(0.5, -0.5);
        Complex result = c.tanh();

        Complex cPos = new Complex(0.5, 0.5);
        Complex resultPos = cPos.tanh();

        Assert.assertEquals(resultPos.getReal(), result.getReal(), EPSILON);
        Assert.assertEquals(-resultPos.getImaginary(), result.getImaginary(), EPSILON);
    }
}
